$n=0;function checkAccess(string $label,bool $want,callable $fn):void{global $n;if($fn()!==$want)throw new RuntimeException($label);$n++;}
foreach([['member',2,'uploads/public.txt',true],['anonymous',0,'uploads/public.txt',false],['outsider',3,'uploads/public.txt',false],['private outsider',2,'uploads/private.txt',false],['private owner',1,'uploads/private.txt',true],['dm member',2,'uploads/dm.txt',true],['dm outsider',3,'uploads/dm.txt',false],['orphan',1,'uploads/orphan.txt',false],['thread owner',1,'uploads/threads/image.png',true],['thread outsider',2,'uploads/threads/image.png',false],['traversal',1,'uploads/../config.php',false],['avatar',1,'uploads/avatars/a.png',false]]as[$l,$u,$p,$want])checkAccess($l,$want,fn()=>AttachmentAccess::canDownload($db,$u,$p,'http://localhost'));
